// The opening. A walled town and a massive castle are built once around world spawn. A new player is seized by the
// King's guards in the town, dragged through the gate and the courtyard into the throne hall, and sent to clear the
// crypt beneath the market. When the crypt's warden falls, the player is brought back to the king and set free.
// The layout (tile offsets, route, positions) comes from castle_layout.js, generated by tools/gen_castle.py.
//
// Player stage (persistentData ddo_stage): 0 = new, 1 = on the first expedition, 2 = free.
// Rhino quirks: `const` inside loops is rejected (use var), and PI is undefined (use PI).
const PI = 3.141592653589793
// Three guards, three voices: Captain Harl (Jerry B.), Guard Voss (Jase) and Sentry Dunn (Garrison).
const CAPTAIN = "§fCaptain Harl§r"
const VOSS = "§fGuard Voss§r"
const DUNN = "§fSentry Dunn§r"
const ESCORT_NAMES = ["Captain Harl", "Guard Voss"]

const SPEECH_SEIZED = [
  "§6King Aldric§r: So. This is the vagrant the wardens dragged in off the high road.",
  "§6King Aldric§r: I am Aldric, and my realm is dying by inches.",
  "§6King Aldric§r: Beneath our soil the dungeons stir. The old vaults, the drowned crypts, the lords who sleep in them. They are waking.",
  "§6King Aldric§r: My knights are dead or fled. You have nothing to lose and a blade to sell. But first, prove you can survive one.",
  "§6King Aldric§r: Beneath the old market well lies a crypt. Its warden, §cGravewick the Hollow§r, has not let a soul out alive. Kill him and come back to me, and you walk free. Run, and you answer to my guards.",
  "§6King Aldric§r: Choose your calling in chat: §e!class warrior§r, §e!class mage§r or §e!class ranger§r. Mind the pressure plates down there. Now go: go dungeoning."
]
const SPEECH_FREED = [
  "§6King Aldric§r: Gravewick is dead? I sent a dozen knights down that stair. And yet here you stand, bleeding on my carpet.",
  "§6King Aldric§r: A promise is a promise. You are free, delver. Take this purse: every lord you topple pays a bounty in coin.",
  "§6King Aldric§r: Spend it with my Quartermaster at the edge of town. Then break the Ancient Remnant in the sunken ruins, the Netherite Monstrosity below the Nether, and the Ender Guardian at the world's end.",
  "§6King Aldric§r: Go. The realm is yours."
]
// Voice lines (ElevenLabs: King = "Elder Rowan", guards = "Jase"). Durations are the clips' lengths in seconds; the scene
// waits for each clip to finish before the next line. Files: kubejs/assets/ddo/sounds/voice/<id>.ogg
const VOICE_SEIZED = ["king_seized_1", "king_seized_2", "king_seized_3", "king_seized_4", "king_seized_5", "king_seized_6"]
const VOICE_SEIZED_SECS = [5.0, 3.5, 9.1, 9.1, 15.9, 10.2]
const VOICE_FREED = ["king_freed_1", "king_freed_2", "king_freed_3", "king_freed_4"]
const VOICE_FREED_SECS = [9.4, 8.4, 12.9, 2.4]
const SPEECH_PAUSE_TICKS = 25
const DRAG_SPEED = 0.3
// Where the crypt sits, relative to the castle origin, and where the player and warden start inside it.
const CRYPT = { origin: [-10, -46, 70], entry: [-0.5, -40, 92.5], warden: [-0.5, -40, 76.5] }

const GUARD_ARMOR = [
  { id: "minecraft:iron_boots", Count: 1 }, { id: "minecraft:iron_leggings", Count: 1 },
  { id: "minecraft:iron_chestplate", Count: 1 }, { id: "minecraft:iron_helmet", Count: 1 }
]
const KING_ARMOR = [
  { id: "minecraft:golden_boots", Count: 1 }, { id: "minecraft:golden_leggings", Count: 1 },
  { id: "minecraft:golden_chestplate", Count: 1 }, { id: "minecraft:golden_helmet", Count: 1 }
]

global.ddoBuild = global.ddoBuild || { queue: null, index: 0, failed: 0, origin: null }
global.ddoIntros = global.ddoIntros || {}

function abs(origin, rel) {
  return { x: origin.x + rel[0], y: origin.y + rel[1], z: origin.z + rel[2] }
}

function castleCommands(o) {
  var C = global.CASTLE
  var r = C.clear
  var cmds = []
  var x0 = o.x + r.x1, x1 = o.x + r.x2, z0 = o.z + r.z1, z1 = o.z + r.z2
  for (var x = x0; x <= x1; x += 32) {
    for (var z = z0; z <= z1; z += 32) {
      var xe = Math.min(x + 31, x1)
      var ze = Math.min(z + 31, z1)
      for (var y = o.y; y < o.y + r.height; y += 32) {
        cmds.push("fill " + x + " " + y + " " + z + " " + xe + " " + Math.min(y + 31, o.y + r.height - 1) + " " + ze + " minecraft:air")
      }
      cmds.push("fill " + x + " " + (o.y - r.depth) + " " + z + " " + xe + " " + (o.y - 2) + " " + ze + " minecraft:dirt")
      cmds.push("fill " + x + " " + (o.y - 1) + " " + z + " " + xe + " " + (o.y - 1) + " " + ze + " minecraft:grass_block")
    }
  }
  C.tiles.forEach(function (t) {
    cmds.push("place template " + t.id + " " + (o.x + t.dx) + " " + (o.y + t.dy) + " " + (o.z + t.dz))
  })
  // the crypt under the market: the trap vault, placed deep in the rock
  cmds.push("place template ddo:trapvault " + (o.x + CRYPT.origin[0]) + " " + (o.y + CRYPT.origin[1]) + " " + (o.z + CRYPT.origin[2]))
  return cmds
}

function spawnNpc(server, type, pos, tag, nbt, extraTags) {
  var entity = server.overworld().createEntity(type)
  entity.setPosition(pos.x, pos.y, pos.z)
  nbt.Tags = [tag].concat(extraTags || [])   // tags in the NBT are reliable; addTag after spawn was not
  entity.mergeNbt(nbt)
  entity.spawn()
  return entity
}

function spawnWarden(server, o) {
  var pos = abs(o, CRYPT.warden)
  // deliberately easy: a first fight should teach the loop, not punish the player
  spawnNpc(server, "minecraft:husk", pos, "ddo_miniboss", {
    PersistenceRequired: true, Glowing: true, Health: 24,
    CustomName: JSON.stringify({ text: "Gravewick the Hollow", color: "dark_red", italic: false }), CustomNameVisible: true,
    Attributes: [{ Name: "generic.max_health", Base: 24 }, { Name: "generic.attack_damage", Base: 2 },
                 { Name: "generic.movement_speed", Base: 0.2 }, { Name: "generic.knockback_resistance", Base: 0 }],
    ArmorItems: [{}, {}, {}, {}],
    HandItems: [{ id: "minecraft:wooden_sword", Count: 1 }, {}]
  })
}

function populate(server, o) {
  var C = global.CASTLE
  spawnNpc(server, "guardvillagers:guard", abs(o, C.king), "ddo_king", {
    NoAI: true, Invulnerable: true, PersistenceRequired: true, Silent: true,
    CustomName: JSON.stringify({ text: "King Aldric the Unbroken", color: "gold", italic: false }), CustomNameVisible: true,
    ArmorItems: KING_ARMOR, HandItems: [{ id: "minecraft:golden_sword", Count: 1 }, {}]
  })
  C.guards.forEach(function (g) {
    spawnNpc(server, "guardvillagers:guard", abs(o, g), "ddo_guard", {
      NoAI: true, Invulnerable: true, PersistenceRequired: true, Silent: true,
      CustomName: JSON.stringify({ text: "Royal Guard", color: "gray", italic: false }),
      ArmorItems: GUARD_ARMOR, HandItems: [{ id: "minecraft:iron_sword", Count: 1 }, {}]
    })
  })
  C.villagers.forEach(function (v) {
    spawnNpc(server, "minecraft:villager", abs(o, v), "ddo_townsfolk", {
      PersistenceRequired: true, VillagerData: { profession: "minecraft:none", level: 1, type: "minecraft:plains" }
    })
  })
  spawnWarden(server, o)
}

// Build the castle a few steps per tick once the world has settled, then populate it.
ServerEvents.tick(function (event) {
  var server = event.server
  var data = server.persistentData
  if (data.getBoolean("ddo_castle_built") || server.tickCount < 30) return
  var build = global.ddoBuild
  if (!build.queue) {
    var spawn = server.overworld().getSharedSpawnPos()
    build.origin = { x: spawn.x, y: spawn.y, z: spawn.z - 60 }
    build.queue = castleCommands(build.origin)
    console.info("castle: building at " + build.origin.x + " " + build.origin.y + " " + build.origin.z + " in " + build.queue.length + " steps")
  }
  for (var i = 0; i < 12 && build.index < build.queue.length; i++) {
    if (!server.runCommandSilent(build.queue[build.index++])) build.failed++
  }
  if (build.index < build.queue.length) return

  populate(server, build.origin)
  data.putInt("ddo_castle_x", build.origin.x)
  data.putInt("ddo_castle_y", build.origin.y)
  data.putInt("ddo_castle_z", build.origin.z)
  data.putBoolean("ddo_castle_built", true)
  console.info("castle: built (" + build.failed + " commands reported no change)")
})

// ---- helpers --------------------------------------------------------------------------------------------------------------

function origin(server) {
  var d = server.persistentData
  return { x: d.getInt("ddo_castle_x"), y: d.getInt("ddo_castle_y"), z: d.getInt("ddo_castle_z") }
}

function playerByName(server, name) {
  var list = server.getPlayerList().getPlayers()
  for (var i = 0; i < list.size(); i++) if (String(list.get(i).username) === name) return list.get(i)
  return null
}

function teleport(server, name, pos, yaw) {
  server.runCommandSilent("tp " + name + " " + pos.x + " " + pos.y + " " + pos.z + " " + yaw + " 8")
}

function holdPlayer(server, name) {
  server.runCommandSilent("effect give " + name + " minecraft:slowness 99999 255 true")
  server.runCommandSilent("effect give " + name + " minecraft:jump_boost 99999 200 true")
  server.runCommandSilent("effect give " + name + " minecraft:resistance 99999 255 true")
}

function releasePlayer(server, name) {
  server.runCommandSilent("effect clear " + name)
}

// ---- 1. seized and dragged to the king ---------------------------------------------------------------------------------

PlayerEvents.loggedIn(function (event) {
  var player = event.player
  if (player.persistentData.getInt("ddo_stage") > 0) return
  var name = String(player.username)
  global.ddoIntros[name] = { phase: "waiting", wp: 0, tick: 0, line: 0 }
  if (!event.server.persistentData.getBoolean("ddo_castle_built")) {
    // the realm is still being raised: black screen until it stands
    event.server.runCommandSilent("effect give " + name + " minecraft:blindness 99999 0 true")
    event.server.runCommandSilent("effect give " + name + " minecraft:slowness 99999 255 true")
    event.server.runCommandSilent("effect give " + name + " minecraft:resistance 99999 255 true")
    event.server.runCommandSilent("title " + name + " title {\"text\":\"The realm awakens...\",\"color\":\"gold\"}")
    event.server.runCommandSilent("title " + name + " subtitle {\"text\":\"raising the castle\",\"color\":\"gray\"}")
  }
  console.info("intro: queued for " + player.username)
})

// ---- 2. the first expedition ---------------------------------------------------------------------------------------------

function startExpedition(server, name) {
  var player = playerByName(server, name)
  if (!player) return
  var o = origin(server)
  var front = abs(o, global.CASTLE.throne_front)
  server.runCommandSilent("kill @e[tag=ddo_escort]")
  releasePlayer(server, name)
  var intro0 = global.ddoIntros[name]
  if (intro0 && intro0.creative) server.runCommandSilent("gamemode creative " + name)
  server.runCommandSilent("spawnpoint " + name + " " + front.x + " " + front.y + " " + front.z)
  server.runCommandSilent("give " + name + " explorerscompass:explorerscompass 1")
  server.runCommandSilent("give " + name + " ftbquests:book 1")
  server.runCommandSilent("give " + name + " lightmanscurrency:wallet_leather 1")
  server.runCommandSilent("give " + name + " minecraft:bread 16")
  server.runCommandSilent("give " + name + " minecraft:torch 32")
  server.runCommandSilent("give " + name + " minecraft:iron_sword 1")
  server.runCommandSilent("give " + name + " minecraft:iron_chestplate 1")
  server.runCommandSilent("give " + name + " minecraft:iron_helmet 1")
  server.runCommandSilent("give " + name + " minecraft:shield 1")
  server.runCommandSilent("give " + name + " minecraft:cooked_beef 12")
  player.persistentData.putInt("ddo_stage", 1)
  enterCrypt(server, name)
  delete global.ddoIntros[name]
  console.info("intro: " + name + " sent to the crypt")
}

function enterCrypt(server, name) {
  var o = origin(server)
  var entry = abs(o, CRYPT.entry)
  server.runCommandSilent("title " + name + " title {\"text\":\"THE CRYPT BELOW\",\"color\":\"dark_red\"}")
  server.runCommandSilent("title " + name + " subtitle {\"text\":\"Kill Gravewick the Hollow\",\"color\":\"gray\"}")
  server.runCommandSilent("tp " + name + " " + entry.x + " " + entry.y + " " + entry.z + " 180 5")
  server.runCommandSilent("effect give " + name + " minecraft:regeneration 600 1 true")
  server.runCommandSilent("effect give " + name + " minecraft:resistance 600 1 true")
  // make sure the warden is alive somewhere down here
  if (server.overworld().getEntities().filter(function (e) { return String(e.tags).indexOf("ddo_miniboss") >= 0 }).length === 0) spawnWarden(server, o)
}

// !dungeon sends a player back down if they died or wandered off before the warden fell.
PlayerEvents.chat(function (event) {
  var text = event.message.trim().toLowerCase()
  var name = String(event.player.username)
  if (text === "!dungeon" && event.player.persistentData.getInt("ddo_stage") === 1) {
    event.cancel()
    enterCrypt(event.server, name)
  }
  if (text === "!skipintro") {
    event.cancel()
    if (global.ddoIntros[name] && global.ddoIntros[name].phase !== "return") startExpedition(event.server, name)
    else if (event.player.persistentData.getInt("ddo_stage") === 0) event.player.persistentData.putInt("ddo_stage", 2)
  }
})

// ---- 3. the warden falls: back to the king, set free --------------------------------------------------------------------

EntityEvents.death(function (event) {
  if (String(event.entity.tags).indexOf("ddo_miniboss") < 0) return
  var server = event.server
  var list = server.getPlayerList().getPlayers()
  for (var i = 0; i < list.size(); i++) {
    var p = list.get(i)
    if (p.persistentData.getInt("ddo_stage") !== 1) continue
    global.ddoIntros[String(p.username)] = { phase: "return", wp: 0, tick: 0, line: 0 }
    p.tell("§cGravewick the Hollow§r crumbles. The crypt falls silent...")
  }
  console.info("intro: the warden is dead")
})

function freePlayer(server, name) {
  var player = playerByName(server, name)
  releasePlayer(server, name)
  if (player) {
    server.runCommandSilent("give " + name + " lightmanscurrency:coin_gold 5")
    server.runCommandSilent("give " + name + " minecraft:diamond 3")
    var f = abs(origin(server), global.CASTLE.throne_front)
    var rocket = "summon minecraft:firework_rocket " + f.x + " " + (f.y + 3) + " " + f.z + " {LifeTime:18,FireworksItem:{id:\"minecraft:firework_rocket\",Count:1,tag:{Fireworks:{Flight:1,Explosions:[{Type:1,Colors:[I;16766720,16711680],FadeColors:[I;16777215]}]}}}}"
    server.runCommandSilent(rocket)
    server.runCommandSilent("playsound minecraft:ui.toast.challenge_complete master " + name + " " + f.x + " " + f.y + " " + f.z + " 0.5 1")
    server.runCommandSilent("particle minecraft:totem_of_undying " + f.x + " " + (f.y + 1) + " " + f.z + " 0.8 1 0.8 0.3 60")
    server.runCommandSilent("title " + name + " title {\"text\":\"YOU ARE FREE\",\"color\":\"gold\",\"bold\":true}")
    server.runCommandSilent("title " + name + " subtitle {\"text\":\"Go dungeoning, delver\",\"color\":\"gray\"}")
    player.persistentData.putInt("ddo_stage", 2)
  }
  delete global.ddoIntros[name]
  console.info("intro: " + name + " is free")
}

// ---- the scene state machine --------------------------------------------------------------------------------------------
// flyover -> seize -> drag -> speech -> (expedition) ... (return) -> speech -> free

const FLYOVER_TICKS = 300
const SEIZE_ARRIVE_TICKS = 40
const SEIZE_APPROACH_TICKS = 45

function say(server, name, json, kind) {
  server.runCommandSilent("title " + name + " " + (kind || "title") + " " + json)
}

function sound(server, name, id, pos, volume, pitch) {
  server.runCommandSilent("playsound " + id + " master " + name + " " + pos.x + " " + pos.y + " " + pos.z + " " + volume + " " + pitch)
}

function voice(server, name, id, pos) {
  server.runCommandSilent("playsound ddo:voice." + id + " voice " + name + " " + pos.x + " " + pos.y + " " + pos.z + " 1.5 1")
}

function lookAt(from, to) {
  var dx = to.x - from.x, dz = to.z - from.z
  var flat = Math.sqrt(dx * dx + dz * dz)
  return { yaw: Math.atan2(-dx, dz) * 180 / PI, pitch: Math.atan2(to.y - from.y, flat) * -180 / PI }
}

ServerEvents.tick(function (event) {
  var server = event.server
  var names = Object.keys(global.ddoIntros)
  if (names.length === 0 || !server.persistentData.getBoolean("ddo_castle_built")) return
  var C = global.CASTLE
  names.forEach(function (name) {
    var intro = global.ddoIntros[name]
    var player = playerByName(server, name)
    if (!player) { delete global.ddoIntros[name]; return }
    var o = origin(server)
    intro.tick++

    // 1. A slow orbit over the castle under the title card, the camera sinking toward the town.
    if (intro.phase === "waiting") {
      intro.creative = player.isCreative()
      server.runCommandSilent("effect clear " + name)
      server.runCommandSilent("gamemode spectator " + name)
      server.runCommandSilent("title " + name + " times 20 80 30")
      say(server, name, "{\"text\":\"DUNGEON DELVER'S ODYSSEY\",\"color\":\"gold\",\"bold\":true}")
      say(server, name, "{\"text\":\"A realm in ruin. A crown with nothing left to lose.\",\"color\":\"gray\"}", "subtitle")
      sound(server, name, "minecraft:block.beacon.activate", abs(o, [0, 0, 60]), 0.4, 0.6)
      intro.phase = "flyover"
      intro.tick = 0
      return
    }

    if (intro.phase === "flyover") {
      var t = intro.tick / FLYOVER_TICKS
      var ease = t * t * (3 - 2 * t)
      var center = { x: o.x + 0.5, y: o.y + 12, z: o.z - 18 }
      var angle = (90 - 230 * ease) * PI / 180
      var radius = 105 - 30 * ease
      var cam = { x: center.x + radius * Math.cos(angle), y: o.y + 72 - 44 * ease, z: center.z + radius * Math.sin(angle) }
      var view = lookAt(cam, center)
      server.runCommandSilent("tp " + name + " " + cam.x + " " + cam.y + " " + cam.z + " " + view.yaw + " " + view.pitch)
      if (intro.tick === 3) console.info("intro: flyover camera at " + Math.round(cam.x) + " " + Math.round(cam.y) + " " + Math.round(cam.z) + " yaw " + Math.round(view.yaw))
      if (intro.tick === 120) say(server, name, "{\"text\":\"The Kingdom of Aldric\",\"color\":\"gold\"}", "actionbar")
      if (intro.tick === 200) say(server, name, "{\"text\":\"The deep stirs below\",\"color\":\"dark_red\"}", "actionbar")
      if (intro.tick === FLYOVER_TICKS - 30) server.runCommandSilent("effect give " + name + " minecraft:blindness 3 0 true")
      if (intro.tick >= FLYOVER_TICKS) {
        server.runCommandSilent("gamemode survival " + name)
        var start = abs(o, C.town_start)
        server.runCommandSilent("tp " + name + " " + start.x + " " + start.y + " " + start.z + " 180 4")
        var way = abs(o, C.waystone)
        server.runCommandSilent("particle minecraft:reverse_portal " + way.x + " " + (way.y + 1) + " " + way.z + " 0.5 1 0.5 0.4 80")
        server.runCommandSilent("particle minecraft:portal " + start.x + " " + (start.y + 1) + " " + start.z + " 0.4 0.8 0.4 0.6 60")
        sound(server, name, "minecraft:block.respawn_anchor.charge", start, 0.5, 0.8)
        say(server, name, "{\"text\":\"The waystone carries you to Aldric's Gate\",\"color\":\"aqua\"}", "actionbar")
        // two guards sprint in from the south end of the street
        intro.escorts = [-1.8, 1.8].map(function (side, i) {
          return spawnNpc(server, "guardvillagers:guard", { x: start.x + side * 4, y: start.y, z: start.z + 18 }, "ddo_escort", {
            NoAI: true, Invulnerable: true, PersistenceRequired: true, Silent: true,
            CustomName: JSON.stringify({ text: ESCORT_NAMES[i], color: "gray", italic: false }),
            ArmorItems: GUARD_ARMOR, HandItems: [{ id: "minecraft:iron_sword", Count: 1 }, {}]
          }, ["ddo_escort_" + i])
        })
        intro.pos = { x: start.x, y: start.y, z: start.z }
        intro.phase = "seize"
        intro.tick = 0
        holdPlayer(server, name)
        say(server, name, "{\"text\":\"You are not welcome here...\",\"color\":\"gray\",\"italic\":true}", "actionbar")
      }
      return
    }

    // 2. The player arrives at the waystone. Guards shout, sprint in, grab an arm each, and the world lurches.
    if (intro.phase === "seize") {
      var home = intro.pos
      var way2 = abs(o, C.waystone)
      if (intro.tick <= SEIZE_ARRIVE_TICKS) {
        // standing in the glow of the waystone, facing it
        server.runCommandSilent("tp " + name + " " + home.x + " " + home.y + " " + home.z + " 180 " + (4 + 1.5 * Math.sin(intro.tick / 4)))
        if (intro.tick % 4 === 0) server.runCommandSilent("particle minecraft:portal " + way2.x + " " + (way2.y + 1.2) + " " + way2.z + " 0.4 1 0.4 0.4 10")
        if (intro.tick === 24) {
          player.tell(CAPTAIN + ": §oThere! By the waystone! Seize him!")
          voice(server, name, "guard_1", { x: home.x, y: home.y, z: home.z + 14 })
        }
        return
      }
      var approach = intro.tick - SEIZE_ARRIVE_TICKS
      if (approach <= SEIZE_APPROACH_TICKS) {
        var k = approach / SEIZE_APPROACH_TICKS
        for (var g = 0; g < 2; g++) {
          var side = g === 0 ? -1.8 : 1.8
          var from = { x: home.x + side * 4, z: home.z + 18 }
          var to = { x: home.x + side, z: home.z + 0.4 }
          var gx = from.x + (to.x - from.x) * k
          var gz = from.z + (to.z - from.z) * k + Math.sin(approach * 1.3) * 0.15   // a running bob
          var face = lookAt({ x: gx, y: home.y, z: gz }, { x: home.x, y: home.y, z: home.z })
          intro.escorts[g].setPosition(gx, home.y, gz)
          intro.escorts[g].setRotation(face.yaw, 0)
        }
        if (approach % 6 === 0) sound(server, name, "minecraft:block.stone.step", home, 0.5, 0.8)
        // the player spins round from the waystone to see them coming
        var turn = Math.min(1, approach / 16)
        server.runCommandSilent("tp " + name + " " + home.x + " " + home.y + " " + home.z + " " + (180 - 180 * turn * turn * (3 - 2 * turn)) + " 5")
        return
      }
      var shakeTicks = approach - SEIZE_APPROACH_TICKS
      if (shakeTicks === 1) {
        sound(server, name, "minecraft:entity.player.attack.strong", home, 0.7, 0.7)
        player.tell(VOSS + ": Got you, vagrant. Up. The King wants a word.")
        voice(server, name, "guard_2", home)
        say(server, name, "{\"text\":\"SEIZED\",\"color\":\"dark_red\",\"bold\":true}")
        server.runCommandSilent("effect give " + name + " minecraft:nausea 4 0 true")
      }
      var shake = Math.max(0, 14 - shakeTicks) * 0.9
      server.runCommandSilent("tp " + name + " " + home.x + " " + home.y + " " + home.z + " " + (Math.sin(shakeTicks * 2.1) * shake) + " " + (6 + Math.cos(shakeTicks * 2.7) * shake))
      if (shakeTicks > 24) { intro.phase = "drag"; intro.wp = 0; intro.tick = 0 }
      return
    }

    // 3. Hauled along the street, through the gate and courtyard, into the keep.
    if (intro.phase === "drag") {
      var target = abs(o, C.waypoints[intro.wp])
      var dx = target.x - intro.pos.x, dz = target.z - intro.pos.z
      var dist = Math.sqrt(dx * dx + dz * dz)
      if (dist <= DRAG_SPEED) {
        intro.wp++
        var banners = { 1: "The Town Gate", 3: "The Courtyard", 5: "The Keep", 6: "The Throne Hall" }
        if (banners[intro.wp]) say(server, name, "{\"text\":\"" + banners[intro.wp] + "\",\"color\":\"gold\"}", "actionbar")
        if (intro.wp === 2) {
          player.tell(DUNN + ": Make way! Make way for the King's justice!")
          voice(server, name, "guard_3", intro.pos)
          sound(server, name, "minecraft:block.iron_door.open", intro.pos, 0.5, 0.7)
        }
        if (intro.wp === 3) {
          player.tell(CAPTAIN + ": Eyes front, vagrant. The King is watching.")
          voice(server, name, "guard_4", intro.pos)
        }
        if (intro.wp === 6) {
          sound(server, name, "minecraft:block.wooden_door.open", intro.pos, 0.5, 0.6)
          player.tell(DUNN + ": On your knees. His Majesty is waiting.")
          voice(server, name, "guard_5", intro.pos)
        }
        if (intro.wp >= C.waypoints.length) { intro.phase = "speech"; intro.tick = 0; intro.line = 0; intro.nextAt = 1; intro.speech = SPEECH_SEIZED }
        return
      }
      intro.pos.x += dx / dist * DRAG_SPEED
      intro.pos.z += dz / dist * DRAG_SPEED
      intro.pos.y = target.y
      var yaw = Math.atan2(-dx, dz) * 180 / PI
      // being hauled along: the head lolls and bobs with each stride
      var swayYaw = yaw + 3.5 * Math.sin(intro.tick / 6)
      var bob = 8 + 3 * Math.sin(intro.tick / 3)
      server.runCommandSilent("tp " + name + " " + intro.pos.x + " " + intro.pos.y + " " + intro.pos.z + " " + swayYaw + " " + bob)
      if (intro.tick % 7 === 0) sound(server, name, "minecraft:block.stone.step", intro.pos, 0.4, 0.9)
      var rad = yaw * PI / 180
      var sideX = Math.cos(rad), sideZ = Math.sin(rad)
      var offsets = [-1.8, 1.8]
      for (var k2 = 0; k2 < offsets.length; k2++) {
        intro.escorts[k2].setPosition(intro.pos.x + sideX * offsets[k2], intro.pos.y, intro.pos.z + sideZ * offsets[k2])
        intro.escorts[k2].setRotation(yaw, 0)
      }
      if (intro.tick === 3) console.info("intro: drag yaw=" + Math.round(yaw) + " player=" + intro.pos.x.toFixed(1) + "," + intro.pos.z.toFixed(1) + " escort0=" + intro.escorts[0].x.toFixed(1) + "," + intro.escorts[0].z.toFixed(1))
      return
    }

    if (intro.phase === "return") {
      var front = abs(o, C.throne_front)
      server.runCommandSilent("effect give " + name + " minecraft:blindness 3 0 true")
      teleport(server, name, front, 0)
      server.runCommandSilent("kill @e[tag=ddo_miniboss]")
      holdPlayer(server, name)
      player.tell("§7You wake on the king's carpet. The throne hall is silent.")
      intro.phase = "speech"
      intro.tick = 0
      intro.line = 0
      intro.nextAt = 1
      intro.speech = SPEECH_FREED
      intro.after = "free"
      return
    }

    // 4. The king turns to face the player, glints, and speaks each line in his own voice, waiting for it to finish.
    if (intro.phase === "speech") {
      if (intro.nextAt === undefined) intro.nextAt = 1
      if (intro.tick >= intro.nextAt) {
        if (intro.line < intro.speech.length) {
          var king = abs(o, C.king)
          var ids = intro.speech === SPEECH_FREED ? VOICE_FREED : VOICE_SEIZED
          var secs = intro.speech === SPEECH_FREED ? VOICE_FREED_SECS : VOICE_SEIZED_SECS
          server.runCommandSilent("tp @e[tag=ddo_king,limit=1] " + king.x + " " + king.y + " " + king.z + " facing entity " + name + " eyes")
          server.runCommandSilent("particle minecraft:enchant " + king.x + " " + (king.y + 2) + " " + king.z + " 0.6 0.8 0.6 0.5 24")
          voice(server, name, ids[intro.line], king)
          player.tell(intro.speech[intro.line])
          intro.nextAt = intro.tick + Math.ceil(secs[intro.line] * 20) + SPEECH_PAUSE_TICKS
          intro.line++
        } else if (intro.after === "free") {
          freePlayer(server, name)
        } else {
          startExpedition(server, name)
        }
      }
    }
  })
})
